# ---------------- results summary
S = []
def s(section, filt, metric, num, den, value, status, source, note=''):
    S.append(dict(section=section, row_filter=filt, metric=metric, numerator=num, denominator=den, value=value,
                  status=status, source=source, population_note=note))
g = list(csv.DictReader(open(os.path.join(R2, 'sender003_attack_grid_r2.csv'))))
for r in g:
    if r['arm'] != 'D-only':
        continue
    filt = f"sensor=003;family={r['family']};severity={r['severity']};schedule={r['schedule']};arm=D-only;version={r['version']}"
    d = int(r['all_attempts']); n = int(r['all_attempt_alarms'])
    s('attack_all_attempt', filt, 'all_attempt_recall', n, d, n / d, 'defined', 'T_R05_metrics.csv population=scheduled_sender', 'pooled C0-C3; dependent events')
    cd = int(r['attempts_in_capable_segments']); cn = int(r['alarms_in_capable_segments'])
    s('attack_capable_segments', filt + f";segments={r['alarm_capable_segments'] or 'none'}", 'recall_where_alarm_possible', cn, cd,
      '' if cd == 0 else cn / cd, 'CANNOT_ALARM_ANY_SEGMENT' if cd == 0 else 'defined', 'sender003_attack_grid_r2.csv', 'thresholds null or 1 excluded')
gm = [r for r in g if r['arm'] != 'D-only']
s('attack_all_attempt', 'sensor=003;arm in (G-only,max(D,G));all 30 attacks;all 4 versions', 'all_attempt_recall', sum(int(r['all_attempt_alarms']) for r in gm), sum(int(r['all_attempts']) for r in gm), 0.0, 'CANNOT_ALARM_ANY_SEGMENT', 'sender003_attack_grid_r2.csv', '240 cells; no threshold')
for r in csv.DictReader(open(os.path.join(R2, 'control_rates_r2.csv'))):
    keep = r['kind'] == 'clean' or (r['kind'] in ('benign', 'identity') and r['sensor'] == '003' and r['arm'] == 'D-only' and r['version'] in ('memoryless', 'EWMA'))
    if not keep:
        continue
    filt = f"kind={r['kind']};family={r['family']};severity={r['severity']};schedule={r['schedule']};sensor={r['sensor']};arm={r['arm']};version={r['version']}"
    segs = ' '.join(f"{x}:{r[x+'_alarms']}/{r[x+'_eligible']}" for x in ('C0', 'C1', 'C2', 'C3'))
    s('control_eligible_fpr', filt, 'eligible_alarm_rate_whole_episode', r['alarms'], r['eligible'], r['eligible_fpr'], r['status'], 'T_R05_metrics.csv', segs)
for r in csv.DictReader(open(os.path.join(R2, 'calibration_cells_r2.csv'))):
    s('calibration', f"test={r['test_segment']};cal={r['calibration_segment']};sensor={r['sensor']};arm={r['arm']};version={r['version']}", 'threshold',
      r['calibration_scores_at_1'], r['saved_known'], r['saved_threshold'], r['meaning'], 'T_R05_clean_support.csv + calibration scores', 'numerator=calibration scores equal 1; denominator=known calibration scores')
for fam, v in pc.items():
    s('paired_effect', f'sensor=003;arm=D-only;version=memoryless;field=C;family={fam}', 'mean_dC_range', v['exact_zero_cells'], v['cells'], f"{v['min']:.6f}..{v['max']:.6f}", 'defined', 'T_R05_paired_effects.csv', 'numerator=cells exactly 0')
for k, v in eo['delay_status'].items():
    s('episode_outcome', 'all interval rows', 'delay_status=' + k, v, eo['interval_rows'], v / eo['interval_rows'], 'defined', 'T_R05_episode_outcomes.csv')
for k in ('attack', 'benign', 'identity'):
    s('attempt_flow', f'kind={k}', 'reader_valid/scheduled', fl[f'{k}:reader_valid'], fl[f'{k}:scheduled_events'], 1.0, 'defined', 'T_R05_attempt_flow.csv', 'injection_failed=%d' % fl[f'{k}:injection_failed'])
for x in json.load(open(os.path.join(R2, 'placeholder_probe.json'))):
    s('placeholder_probe', f"segment={x['segment']};stream={x['stream']};file={x['file']}", 'placeholder_fraction', x['mode_count'], x['points'], x['mode_fraction'], 'defined', 'placeholder_probe.json', f"mode_xyz={x['mode_xyz']};r0a0 {x['r0a0_placeholder_count']}/{x['r0a0_count']}")
with open(os.path.join(PKG, 'results_summary.csv'), 'w', newline='') as h:
    w = csv.DictWriter(h, fieldnames=list(S[0].keys())); w.writeheader(); w.writerows(S)

